const items = $input.all();
const body = items[0].json.body;
const names = body.recipients || [];
const template = body.certificateType || 'Completion';
const course = body.courseName || 'Training Program';
const issueDate = body.issueDate || new Date().toISOString().split('T')[0];
const results = [];
for (const recipient of names) {
  const html = `<!DOCTYPE html><html><head><style>
    body { font-family: 'Georgia', serif; text-align: center; background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); padding: 40px; }
    .cert { background: white; border: 3px solid gold; padding: 60px; margin: 20px auto; max-width: 800px; box-shadow: 0 4px 20px rgba(0,0,0,0.3); }
    h1 { color: #2c3e50; font-size: 36px; border-bottom: 2px solid gold; padding-bottom: 10px; }
    .name { font-size: 28px; color: #8e44ad; margin: 30px 0; }
    .details { font-size: 16px; color: #555; }
  </style></head><body><div class="cert">
    <h1>Certificate of ${template}</h1>
    <p class="details">This is to certify that</p>
    <p class="name">${recipient.name}</p>
    <p class="details">has successfully completed</p>
    <p class="name" style="font-size:22px">${course}</p>
    <p class="details">Issued on: ${issueDate}</p>
    <br/><p class="details">Certificate ID: CERT-${Date.now()}-${Math.random().toString(36).substring(7)}</p>
  </div></body></html>`;
  results.push({ json: { html, recipientName: recipient.name, recipientEmail: recipient.email, course, issueDate } });
}
return results;
